"""Administration and settings contracts."""
from ..builders import operation as op, parameter as p, pages, json_body
from ..schemas import BOOLEAN, INTEGER, STRING, EMAIL, PASSWORD, obj, array, ref, EXAMPLES

OPERATIONS = [
    op('Admin', 'is_admin', 'GET', '/admin/isAdmin', 'Check the current account role', BOOLEAN, True, missing=False, failure=False,
       description='An authenticated non-administrator receives false with msgCode 200.'),
    op('Admin', 'ping_mysql', 'GET', '/admin/pingMySQL', 'Check database connectivity (legacy alias)', missing=-2, failure=-2),
    op('Admin', 'ping_database', 'GET', '/admin/pingDatabase', 'Check PostgreSQL connectivity', missing=-2, failure=-2),
    op('Admin', 'database_info', 'GET', '/admin/databaseInfo', 'Read PostgreSQL and pgvector versions',
       obj({'type': STRING, 'version': STRING, 'address': STRING, 'pgvectorVersion': STRING, 'schemaRevision': STRING}),
       {'type': 'postgresql', 'version': '17', 'address': 'db_postgres:5432', 'pgvectorVersion': '0.8.7', 'schemaRevision': '0001_postgresql'}, failure=-2),
    op('Admin', 'ping_redis', 'GET', '/admin/pingRedis', 'Check Redis connectivity', missing=-2, failure=-2),
    op('Admin', 'get_address', 'GET', '/admin/getAddress', 'Read configured service addresses',
       obj({'mysql': STRING, 'redis': STRING, 'upload': STRING, 'config': STRING}),
       {'mysql': 'db_postgres:5432', 'redis': 'redis:6379', 'upload': '/photoly', 'config': 'PostgreSQL: <setting> table'}, failure=None),
    op('Admin', 'get_settings', 'GET', '/admin/getSettings', 'List application settings',
       {'type': 'object', 'additionalProperties': STRING}, {'SignUp': '1', 'SSafeUUID': '0', 'TokenDuration': '7'}, failure=None),
    op('Admin', 'stop', 'POST', '/admin/stop', 'Stop the entire backend process', code=591023, missing=-2,
       description='DESTRUCTIVE: schedules termination of the entire Gunicorn backend, affecting all users. The response is sent before shutdown. t=1 means scheduled, -2 means not an administrator, -1 means lifecycle control unavailable (for example the development server). Test only in a disposable container.',
       errors={'notAdmin': {'t': -2, 'msgCode': 591023}, 'businessFailure': {'t': -1, 'msgCode': 591023}}),
    op('Admin', 'set_signup_permission', 'POST', '/admin/setSignUpPermission', 'Enable or disable registration', missing=-2, failure=-2,
       params=[p('permission', {'type': 'integer', 'enum': [0, 1]}, '0 disables registration; 1 enables it.', example=1)], form=True),
    op('Admin', 'set_safe_uuid_mode', 'POST', '/admin/setSSafeUUIDMode', 'Set safe UUID mode', missing=-2, failure=-2,
       params=[p('mode', {'type': 'integer', 'enum': [0, 1]}, 'Stored SSafeUUID setting.', example=0)], form=True),
    op('Admin', 'set_token_duration', 'POST', '/admin/setTokenDuration', 'Set login session duration', missing=-2, failure=-2,
       params=[p('days', {'type': 'integer', 'minimum': 0, 'maximum': 365}, 'Session lifetime in days; applies to new sessions. Zero creates immediately expired sessions.', example=7)], form=True,
       errors={'invalidDays': {'t': -1, 'msgCode': 403}}),
    op('Admin', 'get_user_page', 'GET', '/admin/getUserPage', 'List accounts by page', array(ref('User')), [EXAMPLES['User']], params=pages(), shape='page'),
    op('Admin', 'search_user_page', 'GET', '/admin/searchUserPage', 'Search accounts by name or email', array(ref('User')), [EXAMPLES['User']],
       params=pages() + [p('search', STRING, 'Case-insensitive substring of name or email.', False, example='reader')], shape='page'),
    op('Admin', 'list_users', 'GET', '/admin/getUsers', 'List accounts with media counts',
       obj({'users': array({'allOf': [ref('User'), obj({'mediaCount': INTEGER})]}), 'total': INTEGER}),
       {'users': [{**EXAMPLES['User'], 'mediaCount': 1284}], 'total': 48}, missing=-2, failure=-2,
       params=[p('page', {'type': 'integer', 'minimum': 1}, 'One-based page number.', example=1),
               p('rowsPerPage', {'type': 'integer', 'minimum': 1, 'maximum': 200}, 'Number of records per page.', example=20),
               p('search', STRING, 'Case-insensitive substring of name or email.', False, example='reader'),
               p('role', {'type': 'string', 'enum': ['admin', 'user']}, 'Only accounts with this role.', False, example='admin')],
       description='total counts every account matching search and role, for "1-20 of 48" paging.'),
    op('Admin', 'add_user', 'POST', '/admin/addUser', 'Create an account as administrator', missing=-2, failure=-2,
       body=json_body(ref('AdminUserCreate'), {'userName': 'Reader', 'email': 'reader@example.com', 'password': 'example-password', 'role': 'user'})),
    op('Admin', 'delete_user', 'POST', '/admin/deleteUser', 'Permanently delete an account and its files', missing=-2, failure=-2,
       params=[p('userId')], form=True, description='DESTRUCTIVE: removes the target account and all of its owned data.', errors={'notFound': {'t': -5, 'msgCode': 400}}),
    op('Admin', 'get_general_setting', 'POST', '/admin/getGeneralSetting', 'Read one setting', STRING, '7', failure=None,
       params=[p('name', STRING, 'Setting name.', example='TokenDuration')], form=True),
    op('Admin', 'set_general_setting', 'POST', '/admin/setGeneralSetting', 'Update an existing setting', missing=-2,
       params=[p('name', STRING, 'Setting name.', example='TokenDuration'), p('val', STRING, 'Setting value.', example='7')], form=True),
]
for route, field, schema, example in [
    ('resetUserPassword', 'password', PASSWORD, 'example-password'),
    ('resetUserEmail', 'email', EMAIL, 'reader@example.com'),
    ('resetUserRole', 'role', {'type': 'string', 'enum': ['user', 'admin']}, 'user'),
    ('resetUsername', 'userName', STRING, 'Reader'),
]:
    OPERATIONS.append(op('Admin', route, 'POST', '/admin/' + route, 'Reset an account ' + field, missing=-2, failure=-2,
                         body=json_body(obj({'userId': INTEGER, field: schema}), {'userId': 1, field: example})))
